            depot = dpt
    except Exception:
        if dpt is not None:
            depot = dpt

    capacity = get_value("capacity", "vehicle_capacity", "Q")
    try:
        capacity = float(capacity)
    except Exception:
        capacity = None

    demands = get_value("demands", "demand")
    coords = get_value("coords", "coordinates", "locations", "xy")
    dm = get_value("distance_matrix", "distances")

    def is_dict(x):
        try:
            x.keys
            return True
        except Exception:
            return False

    def is_list(x):
        try:
            x.__len__
            x.__getitem__
            return True
        except Exception:
            return False

    def node_ids():
        ids = []
        seen = set()
        try:
            if is_dict(instance):
                for k in ("customers", "nodes"):
                    try:
                        v = instance[k]
                        if is_dict(v):
                            for x in v.keys():
                                if x != depot and x not in seen:
                                    seen.add(x)
                                    ids.append(x)
                            return sorted(ids)
                        for x in v:
                            if x != depot and x not in seen:
                                seen.add(x)
                                ids.append(x)
                            return sorted(ids)
                    except Exception:
                        pass
        except Exception:
            pass
        try:
            if is_dict(demands):
                for x in demands.keys():
                    if x != depot and x not in seen:
                        seen.add(x)
                        ids.append(x)
        except Exception:
            pass
        try:
            if is_list(dm):
                for i in range(len(dm)):
                    if i != depot and i not in seen:
                        seen.add(i)
                        ids.append(i)
        except Exception:
            pass
        try:
            if is_dict(dm):
                for x in dm.keys():
                    if x != depot and x not in seen:
                        seen.add(x)
                        ids.append(x)
                    try:
                        row = dm[x]
                        if is_dict(row):
                            for y in row.keys():
                                if y != depot and y not in seen:
                                    seen.add(y)
                                    ids.append(y)
                    except Exception:
                        pass
        except Exception:
            pass
        try:
            if is_dict(coords):
                for x in coords.keys():
                    if x != depot and x not in seen:
                        seen.add(x)
                        ids.append(x)
        except Exception:
            pass
        try:
            return sorted(ids)
        except Exception:
            return ids

    customers = node_ids()

    def coord(i):
        try:
            if coords is None:
                return None
            if is_dict(coords):
                v = coords.get(i)
            else:
                v = coords[i]
            if is_dict(v) and "x" in v and "y" in v:
                return (v["x"], v["y"])
            return v
        except Exception:
            return None

    def dem(i):
        try:
            if is_dict(demands):
                return demands.get(i, 0)
            if is_list(demands) and isinstance(i, int) and 0 <= i < len(demands):
                return demands[i]
        except Exception:
            pass
        return 0

    def dist(a, b):
        if a == b:
            return 0
        try:
            if is_list(dm):
                return dm[a][b]
        except Exception:
            pass
        try:
            if is_dict(dm):
                row = dm.get(a)
                if is_dict(row) and b in row:
                    return row[b]
        except Exception:
            pass
        ca = coord(a)
        cb = coord(b)
        try:
            if ca is not None and cb is not None:
                ax, ay = ca[0], ca[1]
                bx, by = cb[0], cb[1]
                dx = ax - bx
                dy = ay - by
                return (dx * dx + dy * dy) ** 0.5
        except Exception:
            pass
        try:
            return abs(a - b)
        except Exception:
            return 1

    def route_demand(r):
        s = 0
        for c in r:
            s += dem(c)
        return s

    def route_cost(r):
        if not r:
            return 0
        c = dist(depot, r[0]) + dist(r[-1], depot)
        for i in range(len(r) - 1):
            c += dist(r[i], r[i + 1])
        return c

    def best_insert(route, c):
        if not route:
            return dist(depot, c) * 2, 0
        best = dist(depot, c) + dist(c, depot)
        pos = 0
        x = dist(depot, c) + dist(c, route[0]) - dist(depot, route[0])
        if x < best:
            best, pos = x, 0
        for i in range(len(route) - 1):
            x = dist(route[i], c) + dist(c, route[i + 1]) - dist(route[i], route[i + 1])
            if x < best:
                best, pos = x, i + 1
        x = dist(route[-1], c) + dist(c, depot) - dist(route[-1], depot)
        if x < best:
            best, pos = x, len(route)
        return best, pos

    if capacity is None or capacity <= 0:
        total = 0
        for c in customers:
            total += dem(c)
        capacity = total if total > 0 else 10 ** 18

    unassigned = set(customers)
    routes = []

    while unassigned:
        seed = None
        seed_key = None
        for c in unassigned:
            key = (-dem(c), -dist(depot, c), c)
            if seed is None or key < seed_key:
                seed, seed_key = c, key
        route = [seed]
        load = dem(seed)
        unassigned.remove(seed)

        while True:
            best_c = None
            best_pos = None
            best_key = None
            for c in unassigned:
                dc = dem(c)
                if load + dc > capacity:
                    continue
                gain, pos = best_insert(route, c)
                key = (gain, -dc, dist(depot, c), c)
                if best_c is None or key < best_key:
                    best_c = c
                    best_pos = pos
                    best_key = key
            if best_c is None:
                break
            route.insert(best_pos, best_c)
            load += dem(best_c)
            unassigned.remove(best_c)

        routes.append(route)

    # simple inter-route repair: move customers from overloaded-looking short routes to fill slack
    changed = True
    while changed:
        changed = False
        for i in range(len(routes)):
            r = routes[i]
            if not r:
                continue
            for j in range(len(routes)):
                if i == j:
                    continue
                s = routes[j]
                slack = capacity - route_demand(s)
                best_move = None
                best_delta = None
                for idx, c in enumerate(r):
                    dc = dem(c)
                    if dc > slack:
                        continue
                    old = route_cost(r) + route_cost(s)
                    rr = r[:idx] + r[idx + 1:]
                    ins_gain, pos = best_insert(s, c)
                    ss = s[:pos] + [c] + s[pos:]
                    new = route_cost(rr) + route_cost(ss)
                    delta = new - old
                    if best_move is None or delta < best_delta:
                        best_move = (idx, c, pos)
                        best_delta = delta
                if best_move is not None and best_delta < 0:
                    idx, c, pos = best_move
                    r.pop(idx)
                    s.insert(pos, c)
                    changed = True
                    break
            if changed:
                break

    # cleanup empty routes
    routes = [r for r in routes if r]
    return routes
